with batches as (select value b from jsonb_array_elements($data$[{"key":"kgp-02","lock":2,"items":[{"kind":"trail","peak_slug":"sniezka","key":"sniezka-bialy-jar-czarny-wejscie","fields":{"start_point_name":"Karpacz \u2013 Bia\u0142y Jar","end_point_name":"\u015anie\u017cka"},"broken_fields":{"start_point_name":"Karpacz \u00e2\u20ac\u201c Bia\u00c5\u201ay Jar","end_point_name":"\u00c5\u0161nie\u00c5\u00bcka"},"i18n":{"pl":{"name":"\u015anie\u017cka: wej\u015bcie z Bia\u0142ego Jaru czarnym szlakiem","description":"Podej\u015bcie z Karpacza przez rejon Kopy i Prze\u0142\u0119cz pod \u015anie\u017ck\u0105, z ko\u0144cowym wej\u015bciem Zakosami. Powr\u00f3t wymaga osobnego planu.","notes":"Odwr\u00f3cono GPX PTTK opisany jako zej\u015bcie. Czas 4:15 h podano dla kierunku przeciwnego; 1196 m podej\u015b\u0107 to suma zej\u015b\u0107 z karty \u017ar\u00f3d\u0142owej. Zakosy s\u0142u\u017c\u0105 wej\u015bciu; sprawd\u017a aktualne zasady i zamkni\u0119cia KPN: https://kpn.gov.pl/komunikat-turystyczny"},"en":{"name":"\u015anie\u017cka: black-trail ascent from Bia\u0142y Jar","description":"An ascent from Karpacz via the Kopa area and the pass below \u015anie\u017cka, finishing up the Zakosy zigzags. Plan the return separately.","notes":"PTTK descent GPX reversed. The source gives 4:15 h in reverse; its 1196 m descent becomes ascent. Zakosy is an uphill route; check current KPN rules and closures: https://kpn.gov.pl/komunikat-turystyczny"},"ua":{"name":"\u0421\u043d\u0454\u0436\u043a\u0430: \u043f\u0456\u0434\u0439\u043e\u043c \u0447\u043e\u0440\u043d\u0438\u043c \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u043c \u0456\u0437 Bia\u0142y Jar","description":"\u041f\u0456\u0434\u0439\u043e\u043c \u0456\u0437 \u041a\u0430\u0440\u043f\u0430\u0447\u0430 \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0439\u043e\u043d \u041a\u043e\u043f\u0438 \u0442\u0430 \u043f\u0435\u0440\u0435\u0432\u0430\u043b \u043f\u0456\u0434 \u0421\u043d\u0454\u0436\u043a\u043e\u044e, \u0434\u0430\u043b\u0456 \u0441\u0435\u0440\u043f\u0430\u043d\u0442\u0438\u043d\u043e\u043c Zakosy. \u041f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u043f\u043b\u0430\u043d\u0443\u0439\u0442\u0435 \u043e\u043a\u0440\u0435\u043c\u043e.","notes":"GPX \u0441\u043f\u0443\u0441\u043a\u0443 PTTK \u0440\u043e\u0437\u0432\u0435\u0440\u043d\u0443\u0442\u043e. \u0414\u043b\u044f \u0437\u0432\u043e\u0440\u043e\u0442\u043d\u043e\u0433\u043e \u043d\u0430\u043f\u0440\u044f\u043c\u043a\u0443 \u0434\u0436\u0435\u0440\u0435\u043b\u043e \u0434\u0430\u0454 4:15 \u0433\u043e\u0434; 1196 \u043c \u0441\u043f\u0443\u0441\u043a\u0443 \u0441\u0442\u0430\u044e\u0442\u044c \u043f\u0456\u0434\u0439\u043e\u043c\u043e\u043c. Zakosy \u0432\u0435\u0434\u0435 \u0432\u0433\u043e\u0440\u0443; \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0439 \u0437\u0430\u043a\u0440\u0438\u0442\u0442\u044f KPN: https://kpn.gov.pl/komunikat-turystyczny"},"zh":{"name":"\u015anie\u017cka\uff1a\u4eceBia\u0142y Jar\u6cbf\u9ed1\u8272\u6b65\u9053\u4e0a\u5c71","description":"\u4eceKarpacz\u7ecfKopa\u9644\u8fd1\u53ca\u015anie\u017cka\u4e0b\u65b9\u5c71\u53e3\uff0c\u518d\u6cbfZakosy\u4e4b\u5b57\u5f62\u6b65\u9053\u767b\u9876\u3002\u8fd4\u7a0b\u9700\u53e6\u884c\u89c4\u5212\u3002","notes":"\u5df2\u53cd\u8f6cPTTK\u4e0b\u5c71GPX\u3002\u539f\u8d44\u6599\u6807\u6ce8\u53cd\u5411\u8017\u65f64\u5c0f\u65f615\u5206\uff1b\u539f\u4e0b\u964d1196\u7c73\u5bf9\u5e94\u6b64\u65b9\u5411\u7d2f\u8ba1\u722c\u5347\u3002Zakosy\u7528\u4e8e\u4e0a\u5c71\uff1b\u8bf7\u6838\u5b9eKPN\u901a\u884c\u89c4\u5219\u53ca\u5173\u95ed\u4fe1\u606f\uff1ahttps://kpn.gov.pl/komunikat-turystyczny"}},"broken_i18n":{"pl":{"name":"\u00c5\u0161nie\u00c5\u00bcka: wej\u00c5\u203acie z Bia\u00c5\u201aego Jaru czarnym szlakiem","description":"Podej\u00c5\u203acie z Karpacza przez rejon Kopy i Prze\u00c5\u201a\u00c4\u2122cz pod \u00c5\u0161nie\u00c5\u00bck\u00c4\u2026, z ko\u00c5\u201ecowym wej\u00c5\u203aciem Zakosami. Powr\u00c3\u00b3t wymaga osobnego planu.","notes":"Odwr\u00c3\u00b3cono GPX PTTK opisany jako zej\u00c5\u203acie. Czas 4:15 h podano dla kierunku przeciwnego; 1196 m podej\u00c5\u203a\u00c4\u2021 to suma zej\u00c5\u203a\u00c4\u2021 z karty \u00c5\u00bar\u00c3\u00b3d\u00c5\u201aowej. Zakosy s\u00c5\u201au\u00c5\u00bc\u00c4\u2026 wej\u00c5\u203aciu; sprawd\u00c5\u00ba aktualne zasady i zamkni\u00c4\u2122cia KPN: https://kpn.gov.pl/komunikat-turystyczny"},"en":{"name":"\u00c5\u0161nie\u00c5\u00bcka: black-trail ascent from Bia\u00c5\u201ay Jar","description":"An ascent from Karpacz via the Kopa area and the pass below \u00c5\u0161nie\u00c5\u00bcka, finishing up the Zakosy zigzags. Plan the return separately.","notes":"PTTK descent GPX reversed. The source gives 4:15 h in reverse; its 1196 m descent becomes ascent. Zakosy is an uphill route; check current KPN rules and closures: https://kpn.gov.pl/komunikat-turystyczny"},"ua":{"name":"\u00d0\u00a1\u00d0\u00bd\u00d1\u201d\u00d0\u00b6\u00d0\u00ba\u00d0\u00b0: \u00d0\u00bf\u00d1\u2013\u00d0\u00b4\u00d0\u00b9\u00d0\u00be\u00d0\u00bc \u00d1\u2021\u00d0\u00be\u00d1\u20ac\u00d0\u00bd\u00d0\u00b8\u00d0\u00bc \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a\u00d0\u00be\u00d0\u00bc \u00d1\u2013\u00d0\u00b7 Bia\u00c5\u201ay Jar","description":"\u00d0\u0178\u00d1\u2013\u00d0\u00b4\u00d0\u00b9\u00d0\u00be\u00d0\u00bc \u00d1\u2013\u00d0\u00b7 \u00d0\u0161\u00d0\u00b0\u00d1\u20ac\u00d0\u00bf\u00d0\u00b0\u00d1\u2021\u00d0\u00b0 \u00d1\u2021\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b7 \u00d1\u20ac\u00d0\u00b0\u00d0\u00b9\u00d0\u00be\u00d0\u00bd \u00d0\u0161\u00d0\u00be\u00d0\u00bf\u00d0\u00b8 \u00d1\u201a\u00d0\u00b0 \u00d0\u00bf\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d0\u00b0\u00d0\u00bb \u00d0\u00bf\u00d1\u2013\u00d0\u00b4 \u00d0\u00a1\u00d0\u00bd\u00d1\u201d\u00d0\u00b6\u00d0\u00ba\u00d0\u00be\u00d1\u017d, \u00d0\u00b4\u00d0\u00b0\u00d0\u00bb\u00d1\u2013 \u00d1\u0081\u00d0\u00b5\u00d1\u20ac\u00d0\u00bf\u00d0\u00b0\u00d0\u00bd\u00d1\u201a\u00d0\u00b8\u00d0\u00bd\u00d0\u00be\u00d0\u00bc Zakosy. \u00d0\u0178\u00d0\u00be\u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d0\u00bd\u00d0\u00b5\u00d0\u00bd\u00d0\u00bd\u00d1\u008f \u00d0\u00bf\u00d0\u00bb\u00d0\u00b0\u00d0\u00bd\u00d1\u0192\u00d0\u00b9\u00d1\u201a\u00d0\u00b5 \u00d0\u00be\u00d0\u00ba\u00d1\u20ac\u00d0\u00b5\u00d0\u00bc\u00d0\u00be.","notes":"GPX \u00d1\u0081\u00d0\u00bf\u00d1\u0192\u00d1\u0081\u00d0\u00ba\u00d1\u0192 PTTK \u00d1\u20ac\u00d0\u00be\u00d0\u00b7\u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d0\u00bd\u00d1\u0192\u00d1\u201a\u00d0\u00be. \u00d0\u201d\u00d0\u00bb\u00d1\u008f \u00d0\u00b7\u00d0\u00b2\u00d0\u00be\u00d1\u20ac\u00d0\u00be\u00d1\u201a\u00d0\u00bd\u00d0\u00be\u00d0\u00b3\u00d0\u00be \u00d0\u00bd\u00d0\u00b0\u00d0\u00bf\u00d1\u20ac\u00d1\u008f\u00d0\u00bc\u00d0\u00ba\u00d1\u0192 \u00d0\u00b4\u00d0\u00b6\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00bb\u00d0\u00be \u00d0\u00b4\u00d0\u00b0\u00d1\u201d 4:15 \u00d0\u00b3\u00d0\u00be\u00d0\u00b4; 1196 \u00d0\u00bc \u00d1\u0081\u00d0\u00bf\u00d1\u0192\u00d1\u0081\u00d0\u00ba\u00d1\u0192 \u00d1\u0081\u00d1\u201a\u00d0\u00b0\u00d1\u017d\u00d1\u201a\u00d1\u0152 \u00d0\u00bf\u00d1\u2013\u00d0\u00b4\u00d0\u00b9\u00d0\u00be\u00d0\u00bc\u00d0\u00be\u00d0\u00bc. Zakosy \u00d0\u00b2\u00d0\u00b5\u00d0\u00b4\u00d0\u00b5 \u00d0\u00b2\u00d0\u00b3\u00d0\u00be\u00d1\u20ac\u00d1\u0192; \u00d0\u00bf\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d1\u2013\u00d1\u20ac\u00d1\u201a\u00d0\u00b5 \u00d0\u00bf\u00d1\u20ac\u00d0\u00b0\u00d0\u00b2\u00d0\u00b8\u00d0\u00bb\u00d0\u00b0 \u00d0\u00b9 \u00d0\u00b7\u00d0\u00b0\u00d0\u00ba\u00d1\u20ac\u00d0\u00b8\u00d1\u201a\u00d1\u201a\u00d1\u008f KPN: https://kpn.gov.pl/komunikat-turystyczny"},"zh":{"name":"\u00c5\u0161nie\u00c5\u00bcka\u00ef\u00bc\u0161\u00e4\u00bb\u017dBia\u00c5\u201ay Jar\u00e6\u00b2\u00bf\u00e9\u00bb\u2018\u00e8\u2030\u00b2\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e4\u00b8\u0160\u00e5\u00b1\u00b1","description":"\u00e4\u00bb\u017dKarpacz\u00e7\u00bb\u008fKopa\u00e9\u2122\u201e\u00e8\u00bf\u2018\u00e5\u008f\u0160\u00c5\u0161nie\u00c5\u00bcka\u00e4\u00b8\u2039\u00e6\u2013\u00b9\u00e5\u00b1\u00b1\u00e5\u008f\u00a3\u00ef\u00bc\u0152\u00e5\u2020\u008d\u00e6\u00b2\u00bfZakosy\u00e4\u00b9\u2039\u00e5\u00ad\u2014\u00e5\u00bd\u00a2\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e7\u2122\u00bb\u00e9\u00a1\u00b6\u00e3\u20ac\u201a\u00e8\u00bf\u201d\u00e7\u00a8\u2039\u00e9\u0153\u20ac\u00e5\u008f\u00a6\u00e8\u00a1\u0152\u00e8\u00a7\u201e\u00e5\u02c6\u2019\u00e3\u20ac\u201a","notes":"\u00e5\u00b7\u00b2\u00e5\u008f\u008d\u00e8\u00bd\u00acPTTK\u00e4\u00b8\u2039\u00e5\u00b1\u00b1GPX\u00e3\u20ac\u201a\u00e5\u017d\u0178\u00e8\u00b5\u201e\u00e6\u2013\u2122\u00e6\u00a0\u2021\u00e6\u00b3\u00a8\u00e5\u008f\u008d\u00e5\u0090\u2018\u00e8\u20ac\u2014\u00e6\u2014\u00b64\u00e5\u00b0\u008f\u00e6\u2014\u00b615\u00e5\u02c6\u2020\u00ef\u00bc\u203a\u00e5\u017d\u0178\u00e4\u00b8\u2039\u00e9\u2122\u008d1196\u00e7\u00b1\u00b3\u00e5\u00af\u00b9\u00e5\u00ba\u201d\u00e6\u00ad\u00a4\u00e6\u2013\u00b9\u00e5\u0090\u2018\u00e7\u00b4\u00af\u00e8\u00ae\u00a1\u00e7\u02c6\u00ac\u00e5\u008d\u2021\u00e3\u20ac\u201aZakosy\u00e7\u201d\u00a8\u00e4\u00ba\u017d\u00e4\u00b8\u0160\u00e5\u00b1\u00b1\u00ef\u00bc\u203a\u00e8\u00af\u00b7\u00e6\u00a0\u00b8\u00e5\u00ae\u017eKPN\u00e9\u20ac\u0161\u00e8\u00a1\u0152\u00e8\u00a7\u201e\u00e5\u02c6\u2122\u00e5\u008f\u0160\u00e5\u2026\u00b3\u00e9\u2014\u00ad\u00e4\u00bf\u00a1\u00e6\u0081\u00af\u00ef\u00bc\u0161https://kpn.gov.pl/komunikat-turystyczny"}}},{"kind":"trail","peak_slug":"wielka-sowa","key":"wielka-sowa-sokola-czarny-walimska","fields":{"start_point_name":"Prze\u0142\u0119cz Sokola","end_point_name":"Wielka Sowa"},"broken_fields":{"start_point_name":"Prze\u00c5\u201a\u00c4\u2122cz Sokola","end_point_name":"Wielka Sowa"},"i18n":{"pl":{"name":"Wielka Sowa: d\u0142u\u017cszy czarny wariant przez Prze\u0142\u0119cz Walimsk\u0105","description":"Czarny szlak z Prze\u0142\u0119czy Sokolej na Wielk\u0105 Sow\u0119 przez rejon Rzeczki i Prze\u0142\u0119cz Walimsk\u0105. To d\u0142u\u017cszy wariant, a nie kr\u00f3tkie czerwone wej\u015bcie.","notes":"Parametry PTTK dotycz\u0105 ca\u0142ego czarnego wariantu w jedn\u0105 stron\u0119. Zachowano wszystkie segmenty GPX. Powr\u00f3t i aktualne warunki trzeba sprawdzi\u0107 osobno."},"en":{"name":"Wielka Sowa: longer black route via Prze\u0142\u0119cz Walimska","description":"The black trail from Prze\u0142\u0119cz Sokola to Wielka Sowa via the Rzeczka area and Prze\u0142\u0119cz Walimska. This is the longer option, not the short red ascent.","notes":"PTTK metrics cover the entire one-way black route. All GPX segments are preserved. Plan the return and check current conditions separately."},"ua":{"name":"\u0412\u0435\u043b\u0438\u043a\u0430 \u0421\u043e\u0432\u0430: \u0434\u043e\u0432\u0448\u0438\u0439 \u0447\u043e\u0440\u043d\u0438\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0447\u0435\u0440\u0435\u0437 \u043f\u0435\u0440\u0435\u0432\u0430\u043b Walimska","description":"\u0427\u043e\u0440\u043d\u0438\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u0456\u0437 \u043f\u0435\u0440\u0435\u0432\u0430\u043b\u0443 Sokola \u0447\u0435\u0440\u0435\u0437 \u0440\u0430\u0439\u043e\u043d Rzeczka \u0442\u0430 \u043f\u0435\u0440\u0435\u0432\u0430\u043b Walimska \u043d\u0430 \u0412\u0435\u043b\u0438\u043a\u0443 \u0421\u043e\u0432\u0443. \u0426\u0435 \u0434\u043e\u0432\u0448\u0438\u0439 \u0432\u0430\u0440\u0456\u0430\u043d\u0442, \u0430 \u043d\u0435 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u0447\u0435\u0440\u0432\u043e\u043d\u0438\u0439 \u043f\u0456\u0434\u0439\u043e\u043c.","notes":"\u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438 PTTK \u0441\u0442\u043e\u0441\u0443\u044e\u0442\u044c\u0441\u044f \u0432\u0441\u044c\u043e\u0433\u043e \u0447\u043e\u0440\u043d\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 \u0432 \u043e\u0434\u0438\u043d \u0431\u0456\u043a. \u0423\u0441\u0456 \u0441\u0435\u0433\u043c\u0435\u043d\u0442\u0438 GPX \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e. \u041e\u043a\u0440\u0435\u043c\u043e \u0441\u043f\u043b\u0430\u043d\u0443\u0439\u0442\u0435 \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u0439 \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0443\u043c\u043e\u0432\u0438."},"zh":{"name":"Wielka Sowa\uff1a\u7ecfWalimska\u5c71\u53e3\u7684\u8f83\u957f\u9ed1\u8272\u6b65\u9053","description":"\u4eceSokola\u5c71\u53e3\u7ecfRzeczka\u9644\u8fd1\u53caWalimska\u5c71\u53e3\u524d\u5f80Wielka Sowa\u7684\u9ed1\u8272\u6b65\u9053\u3002\u8fd9\u662f\u8f83\u957f\u8def\u7ebf\uff0c\u5e76\u975e\u8f83\u77ed\u7684\u7ea2\u8272\u767b\u5c71\u7ebf\u3002","notes":"PTTK\u53c2\u6570\u5bf9\u5e94\u5b8c\u6574\u5355\u7a0b\u9ed1\u8272\u6b65\u9053\u3002\u4fdd\u7559\u4e86\u5168\u90e8GPX\u5206\u6bb5\u3002\u8fd4\u7a0b\u4e0e\u5f53\u524d\u8def\u51b5\u9700\u53e6\u884c\u6838\u5b9e\u3002"}},"broken_i18n":{"pl":{"name":"Wielka Sowa: d\u00c5\u201au\u00c5\u00bcszy czarny wariant przez Prze\u00c5\u201a\u00c4\u2122cz Walimsk\u00c4\u2026","description":"Czarny szlak z Prze\u00c5\u201a\u00c4\u2122czy Sokolej na Wielk\u00c4\u2026 Sow\u00c4\u2122 przez rejon Rzeczki i Prze\u00c5\u201a\u00c4\u2122cz Walimsk\u00c4\u2026. To d\u00c5\u201au\u00c5\u00bcszy wariant, a nie kr\u00c3\u00b3tkie czerwone wej\u00c5\u203acie.","notes":"Parametry PTTK dotycz\u00c4\u2026 ca\u00c5\u201aego czarnego wariantu w jedn\u00c4\u2026 stron\u00c4\u2122. Zachowano wszystkie segmenty GPX. Powr\u00c3\u00b3t i aktualne warunki trzeba sprawdzi\u00c4\u2021 osobno."},"en":{"name":"Wielka Sowa: longer black route via Prze\u00c5\u201a\u00c4\u2122cz Walimska","description":"The black trail from Prze\u00c5\u201a\u00c4\u2122cz Sokola to Wielka Sowa via the Rzeczka area and Prze\u00c5\u201a\u00c4\u2122cz Walimska. This is the longer option, not the short red ascent.","notes":"PTTK metrics cover the entire one-way black route. All GPX segments are preserved. Plan the return and check current conditions separately."},"ua":{"name":"\u00d0\u2019\u00d0\u00b5\u00d0\u00bb\u00d0\u00b8\u00d0\u00ba\u00d0\u00b0 \u00d0\u00a1\u00d0\u00be\u00d0\u00b2\u00d0\u00b0: \u00d0\u00b4\u00d0\u00be\u00d0\u00b2\u00d1\u02c6\u00d0\u00b8\u00d0\u00b9 \u00d1\u2021\u00d0\u00be\u00d1\u20ac\u00d0\u00bd\u00d0\u00b8\u00d0\u00b9 \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a \u00d1\u2021\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b7 \u00d0\u00bf\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d0\u00b0\u00d0\u00bb Walimska","description":"\u00d0\u00a7\u00d0\u00be\u00d1\u20ac\u00d0\u00bd\u00d0\u00b8\u00d0\u00b9 \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a \u00d1\u2013\u00d0\u00b7 \u00d0\u00bf\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d0\u00b0\u00d0\u00bb\u00d1\u0192 Sokola \u00d1\u2021\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b7 \u00d1\u20ac\u00d0\u00b0\u00d0\u00b9\u00d0\u00be\u00d0\u00bd Rzeczka \u00d1\u201a\u00d0\u00b0 \u00d0\u00bf\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d0\u00b0\u00d0\u00bb Walimska \u00d0\u00bd\u00d0\u00b0 \u00d0\u2019\u00d0\u00b5\u00d0\u00bb\u00d0\u00b8\u00d0\u00ba\u00d1\u0192 \u00d0\u00a1\u00d0\u00be\u00d0\u00b2\u00d1\u0192. \u00d0\u00a6\u00d0\u00b5 \u00d0\u00b4\u00d0\u00be\u00d0\u00b2\u00d1\u02c6\u00d0\u00b8\u00d0\u00b9 \u00d0\u00b2\u00d0\u00b0\u00d1\u20ac\u00d1\u2013\u00d0\u00b0\u00d0\u00bd\u00d1\u201a, \u00d0\u00b0 \u00d0\u00bd\u00d0\u00b5 \u00d0\u00ba\u00d0\u00be\u00d1\u20ac\u00d0\u00be\u00d1\u201a\u00d0\u00ba\u00d0\u00b8\u00d0\u00b9 \u00d1\u2021\u00d0\u00b5\u00d1\u20ac\u00d0\u00b2\u00d0\u00be\u00d0\u00bd\u00d0\u00b8\u00d0\u00b9 \u00d0\u00bf\u00d1\u2013\u00d0\u00b4\u00d0\u00b9\u00d0\u00be\u00d0\u00bc.","notes":"\u00d0\u0178\u00d0\u00b0\u00d1\u20ac\u00d0\u00b0\u00d0\u00bc\u00d0\u00b5\u00d1\u201a\u00d1\u20ac\u00d0\u00b8 PTTK \u00d1\u0081\u00d1\u201a\u00d0\u00be\u00d1\u0081\u00d1\u0192\u00d1\u017d\u00d1\u201a\u00d1\u0152\u00d1\u0081\u00d1\u008f \u00d0\u00b2\u00d1\u0081\u00d1\u0152\u00d0\u00be\u00d0\u00b3\u00d0\u00be \u00d1\u2021\u00d0\u00be\u00d1\u20ac\u00d0\u00bd\u00d0\u00be\u00d0\u00b3\u00d0\u00be \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a\u00d1\u0192 \u00d0\u00b2 \u00d0\u00be\u00d0\u00b4\u00d0\u00b8\u00d0\u00bd \u00d0\u00b1\u00d1\u2013\u00d0\u00ba. \u00d0\u00a3\u00d1\u0081\u00d1\u2013 \u00d1\u0081\u00d0\u00b5\u00d0\u00b3\u00d0\u00bc\u00d0\u00b5\u00d0\u00bd\u00d1\u201a\u00d0\u00b8 GPX \u00d0\u00b7\u00d0\u00b1\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b6\u00d0\u00b5\u00d0\u00bd\u00d0\u00be. \u00d0\u017e\u00d0\u00ba\u00d1\u20ac\u00d0\u00b5\u00d0\u00bc\u00d0\u00be \u00d1\u0081\u00d0\u00bf\u00d0\u00bb\u00d0\u00b0\u00d0\u00bd\u00d1\u0192\u00d0\u00b9\u00d1\u201a\u00d0\u00b5 \u00d0\u00bf\u00d0\u00be\u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d0\u00bd\u00d0\u00b5\u00d0\u00bd\u00d0\u00bd\u00d1\u008f \u00d0\u00b9 \u00d0\u00bf\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d1\u2013\u00d1\u20ac\u00d1\u201a\u00d0\u00b5 \u00d1\u0192\u00d0\u00bc\u00d0\u00be\u00d0\u00b2\u00d0\u00b8."},"zh":{"name":"Wielka Sowa\u00ef\u00bc\u0161\u00e7\u00bb\u008fWalimska\u00e5\u00b1\u00b1\u00e5\u008f\u00a3\u00e7\u0161\u201e\u00e8\u00be\u0192\u00e9\u2022\u00bf\u00e9\u00bb\u2018\u00e8\u2030\u00b2\u00e6\u00ad\u00a5\u00e9\u0081\u201c","description":"\u00e4\u00bb\u017dSokola\u00e5\u00b1\u00b1\u00e5\u008f\u00a3\u00e7\u00bb\u008fRzeczka\u00e9\u2122\u201e\u00e8\u00bf\u2018\u00e5\u008f\u0160Walimska\u00e5\u00b1\u00b1\u00e5\u008f\u00a3\u00e5\u2030\u008d\u00e5\u00be\u20acWielka Sowa\u00e7\u0161\u201e\u00e9\u00bb\u2018\u00e8\u2030\u00b2\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e3\u20ac\u201a\u00e8\u00bf\u2122\u00e6\u02dc\u00af\u00e8\u00be\u0192\u00e9\u2022\u00bf\u00e8\u00b7\u00af\u00e7\u00ba\u00bf\u00ef\u00bc\u0152\u00e5\u00b9\u00b6\u00e9\u009d\u017e\u00e8\u00be\u0192\u00e7\u0178\u00ad\u00e7\u0161\u201e\u00e7\u00ba\u00a2\u00e8\u2030\u00b2\u00e7\u2122\u00bb\u00e5\u00b1\u00b1\u00e7\u00ba\u00bf\u00e3\u20ac\u201a","notes":"PTTK\u00e5\u008f\u201a\u00e6\u2022\u00b0\u00e5\u00af\u00b9\u00e5\u00ba\u201d\u00e5\u00ae\u0152\u00e6\u2022\u00b4\u00e5\u008d\u2022\u00e7\u00a8\u2039\u00e9\u00bb\u2018\u00e8\u2030\u00b2\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e3\u20ac\u201a\u00e4\u00bf\u009d\u00e7\u2022\u2122\u00e4\u00ba\u2020\u00e5\u2026\u00a8\u00e9\u0192\u00a8GPX\u00e5\u02c6\u2020\u00e6\u00ae\u00b5\u00e3\u20ac\u201a\u00e8\u00bf\u201d\u00e7\u00a8\u2039\u00e4\u00b8\u017d\u00e5\u00bd\u201c\u00e5\u2030\u008d\u00e8\u00b7\u00af\u00e5\u2020\u00b5\u00e9\u0153\u20ac\u00e5\u008f\u00a6\u00e8\u00a1\u0152\u00e6\u00a0\u00b8\u00e5\u00ae\u017e\u00e3\u20ac\u201a"}}},{"kind":"trail","peak_slug":"szczeliniec-wielki","key":"szczeliniec-letnia-trasa-edukacyjna","fields":{"start_point_name":"Prze\u0142\u0119cz pod Szczeli\u0144cem","end_point_name":"Szczeliniec \u2013 pocz\u0105tek schod\u00f3w"},"broken_fields":{"start_point_name":"Prze\u00c5\u201a\u00c4\u2122cz pod Szczeli\u00c5\u201ecem","end_point_name":"Szczeliniec \u00e2\u20ac\u201c pocz\u00c4\u2026tek schod\u00c3\u00b3w"},"i18n":{"pl":{"name":"Szczeliniec Wielki: letnia trasa edukacyjna do zej\u015bciowych schod\u00f3w","description":"Wariant PTTK od prze\u0142\u0119czy przez rejon szczytowy do pocz\u0105tku schod\u00f3w. Obejmuje letni przebieg; nie jest samym doj\u015bciem z Kar\u0142owa do schroniska.","notes":"Metryki dotycz\u0105 tego wariantu PTTK. Labirynt jest sezonowy i jednokierunkowy; zim\u0105 obowi\u0105zuje inny przebieg. Przed wyj\u015bciem sprawd\u017a PNGS: https://pngs.gov.pl/komunikat-turystyczny"},"en":{"name":"Szczeliniec Wielki: summer educational route to the descent stairs","description":"The PTTK route runs from the pass through the summit area to the stairs. It follows the summer itinerary, not just the approach from Kar\u0142\u00f3w to the hut.","notes":"Metrics describe this PTTK variant. The labyrinth is seasonal and one-way; winter access follows a different itinerary. Check PNGS before departure: https://pngs.gov.pl/komunikat-turystyc