u0431\u0440\u0430\u043d\u0430 \u0434\u0456\u043b\u044f\u043d\u043a\u0430 \u0413\u043e\u043b\u043e\u0432\u043d\u043e\u0433\u043e \u0421\u0443\u0434\u0435\u0442\u0441\u044c\u043a\u043e\u0433\u043e \u0448\u043b\u044f\u0445\u0443 \u0432\u0456\u0434 Rozdro\u017ce pod Izerskimi Garbami \u0434\u043e Sine Ska\u0142ki \u0432 \u043c\u0430\u0441\u0438\u0432\u0456 \u0412\u0438\u0441\u043e\u043a\u043e\u0457 \u041a\u043e\u043f\u0438. \u041d\u0430 \u0437\u0430\u043a\u0440\u0438\u0442\u0443 \u0432\u0435\u0440\u0448\u0438\u043d\u0443 \u0412\u0438\u0441\u043e\u043a\u043e\u0457 \u041a\u043e\u043f\u0438 \u043c\u0430\u0440\u0448\u0440\u0443\u0442 \u043d\u0435 \u0432\u0435\u0434\u0435.","notes":"PTTK \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u044f\u0454 \u043f\u0440\u043e \u0437\u0430\u043a\u0440\u0438\u0442\u0442\u044f \u043f\u0456\u0434\u0445\u043e\u0434\u0443 \u043d\u0430 \u0432\u0435\u0440\u0448\u0438\u043d\u0443 \u0434\u043b\u044f \u043e\u0445\u043e\u0440\u043e\u043d\u0438 \u0442\u0435\u0442\u0435\u0440\u0443\u043a\u0430. \u0417\u0430\u043b\u0438\u0448\u0430\u0439\u0442\u0435\u0441\u044f \u043d\u0430 \u043c\u0430\u0440\u043a\u043e\u0432\u0430\u043d\u0456\u0439 \u0441\u0442\u0435\u0436\u0446\u0456; GPX \u043d\u0435 \u043c\u0456\u0441\u0442\u0438\u0442\u044c \u0432\u0456\u0434\u0433\u0430\u043b\u0443\u0436\u0435\u043d\u043d\u044f \u043d\u0430 \u0432\u0435\u0440\u0448\u0438\u043d\u0443. \u041f\u043e\u043a\u0430\u0437\u043d\u0438\u043a\u0438 \u043f\u043e\u0432\u043d\u043e\u0433\u043e \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0443 78,7 \u043a\u043c \u043d\u0435 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0435\u043d\u043e \u043d\u0430 \u043a\u043e\u0440\u043e\u0442\u043a\u0443 \u0434\u0456\u043b\u044f\u043d\u043a\u0443. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u043b\u0456\u0441\u043d\u0438\u0446\u0442\u0432\u0430: https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"},"zh":{"name":"Wysoka Kopa\uff1a\u6cbf\u7ea2\u8272\u6b65\u9053\u5230Sine Ska\u0142ki\uff0c\u4e0d\u767b\u5cf0\u9876","description":"\u622a\u53d6\u82cf\u53f0\u5fb7\u4e3b\u6b65\u9053\u4eceRozdro\u017ce pod Izerskimi Garbami\u81f3Wysoka Kopa\u5c71\u4f53\u5185Sine Ska\u0142ki\u7684\u4e00\u6bb5\uff0c\u4e0d\u901a\u5f80\u5df2\u5173\u95ed\u7684Wysoka Kopa\u5cf0\u9876\u3002","notes":"PTTK\u8d44\u6599\u8bf4\u660e\uff0c\u4e3a\u4fdd\u62a4\u9ed1\u7434\u9e21\uff0c\u5cf0\u9876\u63a5\u8fd1\u8def\u6bb5\u5df2\u5173\u95ed\u3002\u8bf7\u7559\u5728\u6807\u8bb0\u6b65\u9053\u4e0a\uff1bGPX\u4e0d\u542b\u767b\u9876\u652f\u7ebf\u3002\u672a\u5c06\u5b8c\u657478.7\u516c\u91cc\u8def\u7ebf\u7684\u6570\u636e\u5957\u7528\u4e8e\u6b64\u77ed\u6bb5\u3002\u8bf7\u6838\u5b9e\u6797\u533a\u516c\u544a\uff1ahttps://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"}},"broken_i18n":{"pl":{"name":"Wysoka Kopa: czerwony szlak do Sinych Ska\u00c5\u201aek \u00e2\u20ac\u201d bez wej\u00c5\u203acia na szczyt","description":"Wybrany odcinek G\u00c5\u201a\u00c3\u00b3wnego Szlaku Sudeckiego od Rozdro\u00c5\u00bca pod Izerskimi Garbami do Sinych Ska\u00c5\u201aek, w masywie Wysokiej Kopy. Nie prowadzi na zamkni\u00c4\u2122ty wierzcho\u00c5\u201aek Wysokiej Kopy.","notes":"PTTK podaje zamkni\u00c4\u2122cie doj\u00c5\u203acia na szczyt dla ochrony cietrzewia. Pozosta\u00c5\u201e na znakowanym szlaku; GPX nie zawiera odej\u00c5\u203acia na wierzcho\u00c5\u201aek. Nie przypisano parametr\u00c3\u00b3w pe\u00c5\u201anej trasy 78,7 km do kr\u00c3\u00b3tkiego odcinka. Sprawd\u00c5\u00ba komunikaty nadle\u00c5\u203anictwa: https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"},"en":{"name":"Wysoka Kopa: red trail to Sine Ska\u00c5\u201aki \u00e2\u20ac\u201d no summit access","description":"Selected Main Sudetes Trail section from Rozdro\u00c5\u00bce pod Izerskimi Garbami to Sine Ska\u00c5\u201aki in the Wysoka Kopa massif. It does not reach the closed Wysoka Kopa summit.","notes":"PTTK reports summit access closed to protect black grouse. Stay on the marked trail; GPX includes no summit spur. Metrics of the full 78.7 km route were not assigned to this short section. Check forestry announcements: https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"},"ua":{"name":"\u00d0\u2019\u00d0\u00b8\u00d1\u0081\u00d0\u00be\u00d0\u00ba\u00d0\u00b0 \u00d0\u0161\u00d0\u00be\u00d0\u00bf\u00d0\u00b0: \u00d1\u2021\u00d0\u00b5\u00d1\u20ac\u00d0\u00b2\u00d0\u00be\u00d0\u00bd\u00d0\u00b8\u00d0\u00b9 \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a \u00d0\u00b4\u00d0\u00be Sine Ska\u00c5\u201aki \u00e2\u20ac\u201d \u00d0\u00b1\u00d0\u00b5\u00d0\u00b7 \u00d0\u00b2\u00d0\u00b8\u00d1\u2026\u00d0\u00be\u00d0\u00b4\u00d1\u0192 \u00d0\u00bd\u00d0\u00b0 \u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d1\u02c6\u00d0\u00b8\u00d0\u00bd\u00d1\u0192","description":"\u00d0\u2019\u00d0\u00b8\u00d0\u00b1\u00d1\u20ac\u00d0\u00b0\u00d0\u00bd\u00d0\u00b0 \u00d0\u00b4\u00d1\u2013\u00d0\u00bb\u00d1\u008f\u00d0\u00bd\u00d0\u00ba\u00d0\u00b0 \u00d0\u201c\u00d0\u00be\u00d0\u00bb\u00d0\u00be\u00d0\u00b2\u00d0\u00bd\u00d0\u00be\u00d0\u00b3\u00d0\u00be \u00d0\u00a1\u00d1\u0192\u00d0\u00b4\u00d0\u00b5\u00d1\u201a\u00d1\u0081\u00d1\u0152\u00d0\u00ba\u00d0\u00be\u00d0\u00b3\u00d0\u00be \u00d1\u02c6\u00d0\u00bb\u00d1\u008f\u00d1\u2026\u00d1\u0192 \u00d0\u00b2\u00d1\u2013\u00d0\u00b4 Rozdro\u00c5\u00bce pod Izerskimi Garbami \u00d0\u00b4\u00d0\u00be Sine Ska\u00c5\u201aki \u00d0\u00b2 \u00d0\u00bc\u00d0\u00b0\u00d1\u0081\u00d0\u00b8\u00d0\u00b2\u00d1\u2013 \u00d0\u2019\u00d0\u00b8\u00d1\u0081\u00d0\u00be\u00d0\u00ba\u00d0\u00be\u00d1\u2014 \u00d0\u0161\u00d0\u00be\u00d0\u00bf\u00d0\u00b8. \u00d0\u009d\u00d0\u00b0 \u00d0\u00b7\u00d0\u00b0\u00d0\u00ba\u00d1\u20ac\u00d0\u00b8\u00d1\u201a\u00d1\u0192 \u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d1\u02c6\u00d0\u00b8\u00d0\u00bd\u00d1\u0192 \u00d0\u2019\u00d0\u00b8\u00d1\u0081\u00d0\u00be\u00d0\u00ba\u00d0\u00be\u00d1\u2014 \u00d0\u0161\u00d0\u00be\u00d0\u00bf\u00d0\u00b8 \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a \u00d0\u00bd\u00d0\u00b5 \u00d0\u00b2\u00d0\u00b5\u00d0\u00b4\u00d0\u00b5.","notes":"PTTK \u00d0\u00bf\u00d0\u00be\u00d0\u00b2\u00d1\u2013\u00d0\u00b4\u00d0\u00be\u00d0\u00bc\u00d0\u00bb\u00d1\u008f\u00d1\u201d \u00d0\u00bf\u00d1\u20ac\u00d0\u00be \u00d0\u00b7\u00d0\u00b0\u00d0\u00ba\u00d1\u20ac\u00d0\u00b8\u00d1\u201a\u00d1\u201a\u00d1\u008f \u00d0\u00bf\u00d1\u2013\u00d0\u00b4\u00d1\u2026\u00d0\u00be\u00d0\u00b4\u00d1\u0192 \u00d0\u00bd\u00d0\u00b0 \u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d1\u02c6\u00d0\u00b8\u00d0\u00bd\u00d1\u0192 \u00d0\u00b4\u00d0\u00bb\u00d1\u008f \u00d0\u00be\u00d1\u2026\u00d0\u00be\u00d1\u20ac\u00d0\u00be\u00d0\u00bd\u00d0\u00b8 \u00d1\u201a\u00d0\u00b5\u00d1\u201a\u00d0\u00b5\u00d1\u20ac\u00d1\u0192\u00d0\u00ba\u00d0\u00b0. \u00d0\u2014\u00d0\u00b0\u00d0\u00bb\u00d0\u00b8\u00d1\u02c6\u00d0\u00b0\u00d0\u00b9\u00d1\u201a\u00d0\u00b5\u00d1\u0081\u00d1\u008f \u00d0\u00bd\u00d0\u00b0 \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d0\u00ba\u00d0\u00be\u00d0\u00b2\u00d0\u00b0\u00d0\u00bd\u00d1\u2013\u00d0\u00b9 \u00d1\u0081\u00d1\u201a\u00d0\u00b5\u00d0\u00b6\u00d1\u2020\u00d1\u2013; GPX \u00d0\u00bd\u00d0\u00b5 \u00d0\u00bc\u00d1\u2013\u00d1\u0081\u00d1\u201a\u00d0\u00b8\u00d1\u201a\u00d1\u0152 \u00d0\u00b2\u00d1\u2013\u00d0\u00b4\u00d0\u00b3\u00d0\u00b0\u00d0\u00bb\u00d1\u0192\u00d0\u00b6\u00d0\u00b5\u00d0\u00bd\u00d0\u00bd\u00d1\u008f \u00d0\u00bd\u00d0\u00b0 \u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d1\u02c6\u00d0\u00b8\u00d0\u00bd\u00d1\u0192. \u00d0\u0178\u00d0\u00be\u00d0\u00ba\u00d0\u00b0\u00d0\u00b7\u00d0\u00bd\u00d0\u00b8\u00d0\u00ba\u00d0\u00b8 \u00d0\u00bf\u00d0\u00be\u00d0\u00b2\u00d0\u00bd\u00d0\u00be\u00d0\u00b3\u00d0\u00be \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a\u00d1\u0192 78,7 \u00d0\u00ba\u00d0\u00bc \u00d0\u00bd\u00d0\u00b5 \u00d0\u00bf\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00bd\u00d0\u00b5\u00d1\u0081\u00d0\u00b5\u00d0\u00bd\u00d0\u00be \u00d0\u00bd\u00d0\u00b0 \u00d0\u00ba\u00d0\u00be\u00d1\u20ac\u00d0\u00be\u00d1\u201a\u00d0\u00ba\u00d1\u0192 \u00d0\u00b4\u00d1\u2013\u00d0\u00bb\u00d1\u008f\u00d0\u00bd\u00d0\u00ba\u00d1\u0192. \u00d0\u0178\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d1\u2013\u00d1\u20ac\u00d1\u201a\u00d0\u00b5 \u00d0\u00bf\u00d0\u00be\u00d0\u00b2\u00d1\u2013\u00d0\u00b4\u00d0\u00be\u00d0\u00bc\u00d0\u00bb\u00d0\u00b5\u00d0\u00bd\u00d0\u00bd\u00d1\u008f \u00d0\u00bb\u00d1\u2013\u00d1\u0081\u00d0\u00bd\u00d0\u00b8\u00d1\u2020\u00d1\u201a\u00d0\u00b2\u00d0\u00b0: https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"},"zh":{"name":"Wysoka Kopa\u00ef\u00bc\u0161\u00e6\u00b2\u00bf\u00e7\u00ba\u00a2\u00e8\u2030\u00b2\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e5\u02c6\u00b0Sine Ska\u00c5\u201aki\u00ef\u00bc\u0152\u00e4\u00b8\u008d\u00e7\u2122\u00bb\u00e5\u00b3\u00b0\u00e9\u00a1\u00b6","description":"\u00e6\u02c6\u00aa\u00e5\u008f\u2013\u00e8\u2039\u008f\u00e5\u008f\u00b0\u00e5\u00be\u00b7\u00e4\u00b8\u00bb\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e4\u00bb\u017dRozdro\u00c5\u00bce pod Izerskimi Garbami\u00e8\u2021\u00b3Wysoka Kopa\u00e5\u00b1\u00b1\u00e4\u00bd\u201c\u00e5\u2020\u2026Sine Ska\u00c5\u201aki\u00e7\u0161\u201e\u00e4\u00b8\u20ac\u00e6\u00ae\u00b5\u00ef\u00bc\u0152\u00e4\u00b8\u008d\u00e9\u20ac\u0161\u00e5\u00be\u20ac\u00e5\u00b7\u00b2\u00e5\u2026\u00b3\u00e9\u2014\u00ad\u00e7\u0161\u201eWysoka Kopa\u00e5\u00b3\u00b0\u00e9\u00a1\u00b6\u00e3\u20ac\u201a","notes":"PTTK\u00e8\u00b5\u201e\u00e6\u2013\u2122\u00e8\u00af\u00b4\u00e6\u02dc\u017d\u00ef\u00bc\u0152\u00e4\u00b8\u00ba\u00e4\u00bf\u009d\u00e6\u0160\u00a4\u00e9\u00bb\u2018\u00e7\u0090\u00b4\u00e9\u00b8\u00a1\u00ef\u00bc\u0152\u00e5\u00b3\u00b0\u00e9\u00a1\u00b6\u00e6\u017d\u00a5\u00e8\u00bf\u2018\u00e8\u00b7\u00af\u00e6\u00ae\u00b5\u00e5\u00b7\u00b2\u00e5\u2026\u00b3\u00e9\u2014\u00ad\u00e3\u20ac\u201a\u00e8\u00af\u00b7\u00e7\u2022\u2122\u00e5\u0153\u00a8\u00e6\u00a0\u2021\u00e8\u00ae\u00b0\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e4\u00b8\u0160\u00ef\u00bc\u203aGPX\u00e4\u00b8\u008d\u00e5\u0090\u00ab\u00e7\u2122\u00bb\u00e9\u00a1\u00b6\u00e6\u201d\u00af\u00e7\u00ba\u00bf\u00e3\u20ac\u201a\u00e6\u0153\u00aa\u00e5\u00b0\u2020\u00e5\u00ae\u0152\u00e6\u2022\u00b478.7\u00e5\u2026\u00ac\u00e9\u2021\u0152\u00e8\u00b7\u00af\u00e7\u00ba\u00bf\u00e7\u0161\u201e\u00e6\u2022\u00b0\u00e6\u008d\u00ae\u00e5\u00a5\u2014\u00e7\u201d\u00a8\u00e4\u00ba\u017d\u00e6\u00ad\u00a4\u00e7\u0178\u00ad\u00e6\u00ae\u00b5\u00e3\u20ac\u201a\u00e8\u00af\u00b7\u00e6\u00a0\u00b8\u00e5\u00ae\u017e\u00e6\u017e\u2014\u00e5\u0152\u00ba\u00e5\u2026\u00ac\u00e5\u2018\u0160\u00ef\u00bc\u0161https://szklarska.wroclaw.lasy.gov.pl/tymczasowo-zamkniete-szlaki-turystyczne"}}},{"kind":"poi","peak_slug":"wysoka-kopa","key":"https://dolnoslaskie.szlaki.pttk.pl/2035-dolnoslaskie-wysoka-kopa-sine-skalki","fields":{},"broken_fields":{},"i18n":{"pl":{"name":"Sine Ska\u0142ki \u2014 punkt przy czerwonym szlaku","description":"Punkt widokowy i miejsce odpoczynku w masywie Wysokiej Kopy. To osobny punkt przy szlaku, nie zamkni\u0119ty wierzcho\u0142ek Wysokiej Kopy.","tips":"Sprawd\u017a bie\u017c\u0105ce zasady dost\u0119pu u zarz\u0105dcy; nie potwierdzono godzin, cen ani dost\u0119pno\u015bci us\u0142ug."},"en":{"name":"Sine Ska\u0142ki \u2014 landmark on the red trail","description":"A viewpoint and rest location in the Wysoka Kopa massif. This is a separate trail landmark, not the closed Wysoka Kopa summit.","tips":"Check current access rules with the operator; opening hours, prices and service availability are not confirmed."},"ua":{"name":"Sine Ska\u0142ki \u2014 \u043e\u0440\u0456\u0454\u043d\u0442\u0438\u0440 \u043d\u0430 \u0447\u0435\u0440\u0432\u043e\u043d\u043e\u043c\u0443 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0456","description":"\u041e\u0433\u043b\u044f\u0434\u043e\u0432\u0430 \u0442\u043e\u0447\u043a\u0430 \u0442\u0430 \u043c\u0456\u0441\u0446\u0435 \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u043d\u043a\u0443 \u0432 \u043c\u0430\u0441\u0438\u0432\u0456 \u0412\u0438\u0441\u043e\u043a\u043e\u0457 \u041a\u043e\u043f\u0438. \u0426\u0435 \u043e\u043a\u0440\u0435\u043c\u0438\u0439 \u043e\u0440\u0456\u0454\u043d\u0442\u0438\u0440 \u0431\u0456\u043b\u044f \u0441\u0442\u0435\u0436\u043a\u0438, \u0430 \u043d\u0435 \u0437\u0430\u043a\u0440\u0438\u0442\u0430 \u0432\u0435\u0440\u0448\u0438\u043d\u0430 \u0412\u0438\u0441\u043e\u043a\u043e\u0457 \u041a\u043e\u043f\u0438.","tips":"\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0456 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u0443 \u0432 \u0430\u0434\u043c\u0456\u043d\u0456\u0441\u0442\u0440\u0430\u0446\u0456\u0457; \u0433\u043e\u0434\u0438\u043d\u0438 \u0440\u043e\u0431\u043e\u0442\u0438, \u0446\u0456\u043d\u0438 \u0439 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0456\u0441\u0442\u044c \u043f\u043e\u0441\u043b\u0443\u0433 \u043d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043e."},"zh":{"name":"Sine Ska\u0142ki\uff1a\u7ea2\u8272\u6b65\u9053\u65c1\u5730\u6807","description":"Wysoka Kopa\u5c71\u4f53\u5185\u7684\u89c2\u666f\u53ca\u4f11\u606f\u5730\u70b9\u3002\u8fd9\u662f\u6b65\u9053\u65c1\u7684\u72ec\u7acb\u5730\u6807\uff0c\u5e76\u975e\u5df2\u5173\u95ed\u7684Wysoka Kopa\u5cf0\u9876\u3002","tips":"\u8bf7\u5411\u7ba1\u7406\u65b9\u6838\u5b9e\u5f53\u524d\u901a\u884c\u89c4\u5b9a\uff1b\u672a\u786e\u8ba4\u5f00\u653e\u65f6\u95f4\u3001\u8d39\u7528\u6216\u670d\u52a1\u53ef\u7528\u6027\u3002"}},"broken_i18n":{"pl":{"name":"Sine Ska\u00c5\u201aki \u00e2\u20ac\u201d punkt przy czerwonym szlaku","description":"Punkt widokowy i miejsce odpoczynku w masywie Wysokiej Kopy. To osobny punkt przy szlaku, nie zamkni\u00c4\u2122ty wierzcho\u00c5\u201aek Wysokiej Kopy.","tips":"Sprawd\u00c5\u00ba bie\u00c5\u00bc\u00c4\u2026ce zasady dost\u00c4\u2122pu u zarz\u00c4\u2026dcy; nie potwierdzono godzin, cen ani dost\u00c4\u2122pno\u00c5\u203aci us\u00c5\u201aug."},"en":{"name":"Sine Ska\u00c5\u201aki \u00e2\u20ac\u201d landmark on the red trail","description":"A viewpoint and rest location in the Wysoka Kopa massif. This is a separate trail landmark, not the closed Wysoka Kopa summit.","tips":"Check current access rules with the operator; opening hours, prices and service availability are not confirmed."},"ua":{"name":"Sine Ska\u00c5\u201aki \u00e2\u20ac\u201d \u00d0\u00be\u00d1\u20ac\u00d1\u2013\u00d1\u201d\u00d0\u00bd\u00d1\u201a\u00d0\u00b8\u00d1\u20ac \u00d0\u00bd\u00d0\u00b0 \u00d1\u2021\u00d0\u00b5\u00d1\u20ac\u00d0\u00b2\u00d0\u00be\u00d0\u00bd\u00d0\u00be\u00d0\u00bc\u00d1\u0192 \u00d0\u00bc\u00d0\u00b0\u00d1\u20ac\u00d1\u02c6\u00d1\u20ac\u00d1\u0192\u00d1\u201a\u00d1\u2013","description":"\u00d0\u017e\u00d0\u00b3\u00d0\u00bb\u00d1\u008f\u00d0\u00b4\u00d0\u00be\u00d0\u00b2\u00d0\u00b0 \u00d1\u201a\u00d0\u00be\u00d1\u2021\u00d0\u00ba\u00d0\u00b0 \u00d1\u201a\u00d0\u00b0 \u00d0\u00bc\u00d1\u2013\u00d1\u0081\u00d1\u2020\u00d0\u00b5 \u00d0\u00b2\u00d1\u2013\u00d0\u00b4\u00d0\u00bf\u00d0\u00be\u00d1\u2021\u00d0\u00b8\u00d0\u00bd\u00d0\u00ba\u00d1\u0192 \u00d0\u00b2 \u00d0\u00bc\u00d0\u00b0\u00d1\u0081\u00d0\u00b8\u00d0\u00b2\u00d1\u2013 \u00d0\u2019\u00d0\u00b8\u00d1\u0081\u00d0\u00be\u00d0\u00ba\u00d0\u00be\u00d1\u2014 \u00d0\u0161\u00d0\u00be\u00d0\u00bf\u00d0\u00b8. \u00d0\u00a6\u00d0\u00b5 \u00d0\u00be\u00d0\u00ba\u00d1\u20ac\u00d0\u00b5\u00d0\u00bc\u00d0\u00b8\u00d0\u00b9 \u00d0\u00be\u00d1\u20ac\u00d1\u2013\u00d1\u201d\u00d0\u00bd\u00d1\u201a\u00d0\u00b8\u00d1\u20ac \u00d0\u00b1\u00d1\u2013\u00d0\u00bb\u00d1\u008f \u00d1\u0081\u00d1\u201a\u00d0\u00b5\u00d0\u00b6\u00d0\u00ba\u00d0\u00b8, \u00d0\u00b0 \u00d0\u00bd\u00d0\u00b5 \u00d0\u00b7\u00d0\u00b0\u00d0\u00ba\u00d1\u20ac\u00d0\u00b8\u00d1\u201a\u00d0\u00b0 \u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d1\u02c6\u00d0\u00b8\u00d0\u00bd\u00d0\u00b0 \u00d0\u2019\u00d0\u00b8\u00d1\u0081\u00d0\u00be\u00d0\u00ba\u00d0\u00be\u00d1\u2014 \u00d0\u0161\u00d0\u00be\u00d0\u00bf\u00d0\u00b8.","tips":"\u00d0\u0178\u00d0\u00b5\u00d1\u20ac\u00d0\u00b5\u00d0\u00b2\u00d1\u2013\u00d1\u20ac\u00d1\u201a\u00d0\u00b5 \u00d0\u00b0\u00d0\u00ba\u00d1\u201a\u00d1\u0192\u00d0\u00b0\u00d0\u00bb\u00d1\u0152\u00d0\u00bd\u00d1\u2013 \u00d0\u00bf\u00d1\u20ac\u00d0\u00b0\u00d0\u00b2\u00d0\u00b8\u00d0\u00bb\u00d0\u00b0 \u00d0\u00b4\u00d0\u00be\u00d1\u0081\u00d1\u201a\u00d1\u0192\u00d0\u00bf\u00d1\u0192 \u00d0\u00b2 \u00d0\u00b0\u00d0\u00b4\u00d0\u00bc\u00d1\u2013\u00d0\u00bd\u00d1\u2013\u00d1\u0081\u00d1\u201a\u00d1\u20ac\u00d0\u00b0\u00d1\u2020\u00d1\u2013\u00d1\u2014; \u00d0\u00b3\u00d0\u00be\u00d0\u00b4\u00d0\u00b8\u00d0\u00bd\u00d0\u00b8 \u00d1\u20ac\u00d0\u00be\u00d0\u00b1\u00d0\u00be\u00d1\u201a\u00d0\u00b8, \u00d1\u2020\u00d1\u2013\u00d0\u00bd\u00d0\u00b8 \u00d0\u00b9 \u00d0\u00b4\u00d0\u00be\u00d1\u0081\u00d1\u201a\u00d1\u0192\u00d0\u00bf\u00d0\u00bd\u00d1\u2013\u00d1\u0081\u00d1\u201a\u00d1\u0152 \u00d0\u00bf\u00d0\u00be\u00d1\u0081\u00d0\u00bb\u00d1\u0192\u00d0\u00b3 \u00d0\u00bd\u00d0\u00b5 \u00d0\u00bf\u00d1\u2013\u00d0\u00b4\u00d1\u201a\u00d0\u00b2\u00d0\u00b5\u00d1\u20ac\u00d0\u00b4\u00d0\u00b6\u00d0\u00b5\u00d0\u00bd\u00d0\u00be."},"zh":{"name":"Sine Ska\u00c5\u201aki\u00ef\u00bc\u0161\u00e7\u00ba\u00a2\u00e8\u2030\u00b2\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e6\u2014\u0081\u00e5\u0153\u00b0\u00e6\u00a0\u2021","description":"Wysoka Kopa\u00e5\u00b1\u00b1\u00e4\u00bd\u201c\u00e5\u2020\u2026\u00e7\u0161\u201e\u00e8\u00a7\u201a\u00e6\u2122\u00af\u00e5\u008f\u0160\u00e4\u00bc\u2018\u00e6\u0081\u00af\u00e5\u0153\u00b0\u00e7\u201a\u00b9\u00e3\u20ac\u201a\u00e8\u00bf\u2122\u00e6\u02dc\u00af\u00e6\u00ad\u00a5\u00e9\u0081\u201c\u00e6\u2014\u0081\u00e7\u0161\u201e\u00e7\u2039\u00ac\u00e7\u00ab\u2039\u00e5\u0153\u00b0\u00e6\u00a0\u2021\u00ef\u00bc\u0152\u00e5\u00b9\u00b6\u00e9\u009d\u017e\u00e5\u00b7\u00b2\u00e5\u2026\u00b3\u00e9\u2014\u00ad\u00e7\u0161\u201eWysoka Kopa\u00e5\u00b3\u00b0\u00e9\u00a1\u00b6\u00e3\u20ac\u201a","tips":"\u00e8\u00af\u00b7\u00e5\u0090\u2018\u00e7\u00ae\u00a1\u00e7\u0090\u2020\u00e6\u2013\u00b9\u00e6\u00a0\u00b8\u00e5\u00ae\u017e\u00e5\u00bd\u201c\u00e5\u2030\u008d\u00e9\u20ac\u0161\u00e8\u00a1\u0152\u00e8\u00a7\u201e\u00e5\u00ae\u0161\u00ef\u00bc\u203a\u00e6\u0153\u00aa\u00e7\u00a1\u00ae\u00e8\u00ae\u00a4\u00e5\u00bc\u20ac\u00e6\u201d\u00be\u00e6\u2014\u00b6\u00e9\u2014\u00b4\u00e3\u20ac\u0081\u00e8\u00b4\u00b9\u00e7\u201d\u00a8\u00e6\u02c6\u2013\u00e6\u0153\u008d\u00e5\u0160\u00a1\u00e5\u008f\u00af\u00e7\u201d\u00a8\u00e6\u20ac\u00a7\u00e3\u20ac\u201a"}}}]}]$data$::jsonb)),
expected as (select b->>'key' batch_key,value e from batches cross join lateral jsonb_array_elements(b->'items')),
checks as (
 select batch_key,e->>'kind' kind,e->>'key' identity,
  case when e->>'kind'='trail' then t.id else o.id end id,
  case when e->>'kind'='trail' then
   t.start_point_name is not distinct from e->'fields'->>'start_point_name' and t.end_point_name is not distinct from e->'fields'->>'end_point_name'
   and (select count(*)=4 and bool_and(coalesce((to_jsonb(i)-'trail_id'-'lang')=e->'i18n'->i.lang,false)) from public.trails_i18n i where trail_id=t.id)
  else (select count(*)=4 and bool_and(coalesce((to_jsonb(i)-'poi_id'-'lang')=e->'i18n'->i.lang,false)) from public.pois_i18n i where poi_id=o.id) end exact_text_match
 from expected left join public.peaks p on p.slug=e->>'peak_slug'
 left join public.trails t on e->>'kind'='trail' and t.slug=e->>'key' and t.peak_id=p.id
 left join public.pois o on e->>'kind'='poi' and o.source_url=e->>'key' and o.peak_id=p.id
)
select batch_key, count(*) expected_records,count(id) found_records,
 count(*) filter(where exact_text_match is true) correct_text_records,
 coalesce(jsonb_agg(identity) filter(where id is null or exact_text_match is not true),'[]'::jsonb) remaining_issues
from checks group by batch_key order by batch_key;
